const input = $json.body ?? $json;
const arr = v => Array.isArray(v) ? v : [];
const truthy = v => v === true || v === "true" || v === 1 || v === "1";
const blockers = arr(input.blockers);
const requiredDocs = arr(input.required_documents);
const suppliedDocs = arr(input.supplied_documents);
const parties = arr(input.parties);
const requiredRoles = arr(input.required_roles);
const assignedRoles = arr(input.assigned_roles);
const readiness = input.transaction_readiness ?? {};
const recovery = input.recovery ?? {};
const packageState = input.closing_package ?? {};

const identityComplete = Boolean(input.deal_id && input.lead_id && input.property_id);
const readinessReconciled =
  truthy(input.transaction_readiness_reconciled) ||
  ["reconciled","ready","transaction_ready"].includes(String(readiness.status || "").toLowerCase());

const recoveryClear =
  !truthy(input.recovery_required) &&
  !truthy(recovery.active) &&
  !["pending","in_progress","failed","blocked"].includes(String(recovery.status || "").toLowerCase());

const blockersClear = blockers.length === 0;
const docsComplete = requiredDocs.length === 0 ||
  requiredDocs.every(req => suppliedDocs.some(doc => String(doc.id ?? doc) === String(req.id ?? req)));

const rolesComplete = requiredRoles.length === 0 ||
  requiredRoles.every(role => assignedRoles.some(assigned =>
    String(assigned.role ?? assigned) === String(role.role ?? role)
  ));

const partiesComplete = parties.length >= 2 ||
  Boolean(input.seller && (input.buyer || input.assignee));

const executedAgreement = truthy(input.executed_agreement) ||
  ["executed","signed","fully_executed"].includes(String(input.agreement_status || "").toLowerCase());

const closingDateValid = !input.closing_date || !Number.isNaN(new Date(input.closing_date).getTime());
const price = Number(input.contract_price ?? input.agreed_price ?? input.purchase_price);
const mao = Number(input.dynamic_mao ?? input.mao);
const priceProtected = !Number.isFinite(price) || !Number.isFinite(mao) || price <= mao;

const packageAlreadyFinalized =
  truthy(packageState.finalized) ||
  ["finalized","ready","complete"].includes(String(packageState.status || "").toLowerCase());

const packageReady =
  identityComplete &&
  readinessReconciled &&
  recoveryClear &&
  blockersClear &&
  docsComplete &&
  rolesComplete &&
  partiesComplete &&
  executedAgreement &&
  closingDateValid &&
  priceProtected;

let status = "package_finalization_required";
let nextWorkflow = "WF-277";
let humanReview = true;

if (!identityComplete) {
  status = "blocked_missing_identity";
  nextWorkflow = "WF-126";
} else if (!recoveryClear) {
  status = "recovery_not_cleared";
  nextWorkflow = "WF-274";
} else if (!readinessReconciled) {
  status = "transaction_readiness_not_reconciled";
  nextWorkflow = "WF-275";
} else if (!blockersClear || !closingDateValid || !priceProtected) {
  status = "blocked";
  nextWorkflow = "WF-126";
} else if (!docsComplete || !rolesComplete || !partiesComplete || !executedAgreement) {
  status = "package_evidence_incomplete";
  nextWorkflow = "WF-276";
} else if (packageAlreadyFinalized) {
  status = "package_already_finalized";
  nextWorkflow = "WF-277";
} else if (packageReady) {
  status = "closing_package_ready_for_finalization";
  nextWorkflow = "WF-277";
}

return [{
  json: {
    ...input,
    workflow: "WF-276",
    workflow_name: "Transaction Readiness Reconciliation → Closing Package Finalization Controller",
    status,
    package_finalization: {
      identity_complete: identityComplete,
      transaction_readiness_reconciled: readinessReconciled,
      recovery_clear: recoveryClear,
      blockers_clear: blockersClear,
      required_documents_complete: docsComplete,
      required_roles_complete: rolesComplete,
      parties_complete: partiesComplete,
      executed_agreement: executedAgreement,
      closing_date_valid: closingDateValid,
      price_protected_by_mao: priceProtected,
      package_already_finalized: packageAlreadyFinalized,
      ready: packageReady
    },
    next_workflow: nextWorkflow,
    human_review_required: humanReview,
    routing_reason: status,
    audit: {
      event_type: "transaction_readiness_reconciliation_package_finalization",
      idempotency_key: input.idempotency_key || `wf-276:${input.deal_id || "unknown"}:${input.package_id || "none"}:${input.version || 1}`
    }
  }
}];
